CREATE OR REPLACE FUNCTION public.org_can(cap text,rid uuid DEFAULT NULL) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT org_has_role(auth.uid(),'admin') OR CASE cap WHEN 'people' THEN false WHEN 'campaigns' THEN org_has_role(auth.uid(),'hr') WHEN 'approve' THEN org_has_role(auth.uid(),'hr') WHEN 'results' THEN org_has_role(auth.uid(),'hr') OR org_assigned(auth.uid(),rid,'hiring_manager') WHEN 'decision' THEN org_assigned(auth.uid(),rid,'hiring_manager') WHEN 'analysis' THEN org_has_role(auth.uid(),'analyst') WHEN 'fairness' THEN org_has_role(auth.uid(),'analyst') OR org_has_role(auth.uid(),'hr') WHEN 'sme' THEN org_assigned(auth.uid(),rid,'sme') WHEN 'score' THEN org_assigned(auth.uid(),rid,'rater') ELSE false END $$; DROP POLICY battery_read ON public.assessment_batteries; CREATE POLICY battery_read ON public.assessment_batteries FOR SELECT TO authenticated USING(org_can('analysis',id)); CREATE FUNCTION public.onboarding_batteries() RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE b assessment_batteries;p jsonb;result jsonb:='[]';sid text;BEGIN FOR b IN SELECT * FROM assessment_batteries LOOP IF org_can('analysis',b.id) THEN p:=b.payload;ELSIF org_can('approve',b.id) OR org_can('results',b.id) OR org_can('sme',b.id) THEN SELECT a.source_id INTO sid FROM org_assignments a JOIN org_people o ON o.id=a.person_id WHERE a.role_id=b.id AND a.permission='sme' AND o.user_id=auth.uid();p:=b.payload||jsonb_build_object('ratings',(SELECT coalesce(jsonb_agg(value),'[]') FROM jsonb_array_elements(b.payload->'ratings') WHERE sid IS NOT NULL AND value->>'source_id'=sid),'incidents',(SELECT coalesce(jsonb_agg(value),'[]') FROM jsonb_array_elements(b.payload->'incidents') WHERE sid IS NOT NULL AND value->>'source_id'=sid));ELSE CONTINUE;END IF;result:=result||jsonb_build_array(p);END LOOP;RETURN result;END $$; CREATE FUNCTION public.onboarding_sme_save(v jsonb) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE b assessment_batteries;sid text;ratings jsonb;incidents jsonb;BEGIN PERFORM pg_advisory_xact_lock(811112026);SELECT * INTO b FROM assessment_batteries WHERE id=(v->>'id')::uuid FOR UPDATE;IF b.id IS NULL OR NOT org_can('sme',b.id) THEN RAISE EXCEPTION 'Assigned SME required';END IF;SELECT a.source_id INTO sid FROM org_assignments a JOIN org_people p ON p.id=a.person_id WHERE a.role_id=b.id AND a.permission='sme' AND p.user_id=auth.uid();IF sid IS NULL OR EXISTS(SELECT 1 FROM jsonb_array_elements(v->'ratings') WHERE value->>'source_id'<>sid) OR EXISTS(SELECT 1 FROM jsonb_array_elements(v->'incidents') WHERE value->>'source_id'<>sid) THEN RAISE EXCEPTION 'Only your own judgments may be saved';END IF;SELECT coalesce(jsonb_agg(value),'[]') INTO ratings FROM jsonb_array_elements(b.payload->'ratings') WHERE value->>'source_id'<>sid;SELECT coalesce(jsonb_agg(value),'[]') INTO incidents FROM jsonb_array_elements(b.payload->'incidents') WHERE value->>'source_id'<>sid;UPDATE assessment_batteries SET payload=b.payload||jsonb_build_object('ratings',ratings||(v->'ratings'),'incidents',incidents||(v->'incidents')) WHERE id=b.id;RETURN true;END $$; REVOKE ALL ON FUNCTION onboarding_batteries(),onboarding_sme_save(jsonb) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION onboarding_batteries(),onboarding_sme_save(jsonb) TO authenticated;